insert into qyr_packs (pack_id, title, kind, notice) values
  ('QYRIS-INDUSTRY-001', 'QYRIS Industry Template', 'INDUSTRY', 'The same QYRIS grammar projected across six domains. Sixteen axes times six domains. Every QUESTION is authored per domain; YIELD, REASON and INSPECT are produced from the axis invariant plus the domain lexicon; SAFEGUARD is authored only where a generic one would be unsafe.')
insert into qyr_axes (axis_id, label, invariant) values
  ('MONEY', 'MONEY', 'What value exists, who holds it, and who may move it without asking.'),
  ('DEBT', 'DEBT', 'What obligation is already owed, to whom, and who it follows when things end.'),
  ('CHILDREN', 'CHILDREN', 'Who is dependent on this, who comes next, and what they are owed regardless of the outcome.'),
  ('FAMILY_BOUNDARIES', 'FAMILY BOUNDARIES', 'Who outside the core may decide, enter, know — and who says no to them.'),
  ('FAITH_WORLDVIEW', 'FAITH / WORLDVIEW', 'What creed governs practice here, whose ruling settles a dispute, and what happens if someone stops believing it.'),
  ('SEX_INTIMACY', 'CLOSENESS & POWER', 'Where closeness and power meet, and how a no is heard by the person with less of it.'),
  ('HOUSEHOLD_LABOR', 'UNSEEN LABOUR', 'The work that keeps this running that nobody credits, and who is carrying it.'),
  ('CONFLICT', 'CONFLICT', 'What happens under pressure, and what is never permitted no matter how justified it feels.'),
  ('HEALTH_CARE', 'CAPACITY & CARE', 'What happens when someone here cannot continue, and who decides for them.'),
  ('CAREERS', 'PATHS', 'Whose path moves first when both cannot be accommodated, and who decided that.'),
  ('GEOGRAPHY', 'PLACE', 'Where this happens, who is farther from home, and who is less safe in that place.'),
  ('PRIVACY', 'PRIVACY', 'What stays a person''s own here, and whether access granted can be withdrawn.'),
  ('TRUST', 'TRUST', 'What would end this, and what is already unresolved and unspoken.'),
  ('FUTURE_CHANGE', 'FUTURE CHANGE', 'What change would this survive, and when is it deliberately revisited.'),
  ('DEAL_BREAKERS', 'DEAL BREAKERS', 'The absolute limits, plus the floor that applies whether anyone named it or not.'),
  ('REPAIR', 'REPAIR', 'What actually repairs harm here, in actions, and what happens when the same harm recurs.')
