insert into qyr_domains (domain_id, label) values
  ('MUSIC', 'MUSIC'),
  ('COMEDY', 'COMEDY'),
  ('BUSINESS', 'BUSINESS'),
  ('RELIGION', 'RELIGION'),
  ('EDUCATION', 'EDUCATION'),
  ('FAMILY', 'FAMILY')
insert into qyr_nodes (node_id, pack_id, parent_id, cluster_id, label, depth, ordinal, question, yield, reason, inspect, safeguard) values
  ('MUSIC.MONEY', 'QYRIS-INDUSTRY-001', null, 'MUSIC', 'MUSIC · MONEY', 0, 0, 'What are the master, publishing, performance and sync splits on this record, in writing, signed by everyone in the room before release?', 'A written map of master, publishing, performance and sync income with a named holder and a named mover for each line.', 'In music, the money fight is almost always a fight about a number one party never saw.', 'Check the stated position against the split sheet, the session log and the registration. An impression is not a figure.', 'Disclosure is mutual. The uncredited contributor is not asked to disclose to someone who has disclosed nothing.'),
  ('MUSIC.DEBT', 'QYRIS-INDUSTRY-001', null, 'MUSIC', 'MUSIC · DEBT', 0, 1, 'What advance, studio cost, marketing spend or producer fee is recoupable against whose income, and at what point does anyone actually get paid?', 'An obligation schedule with a legal owner and an end condition per line.', 'Obligations that predate the arrangement do not end when the arrangement begins.', 'Read the instrument. A remembered obligation is an estimate; a signed one is evidence.', 'A disclosed obligation is a shared map, not a file kept on the uncredited contributor for later use.'),
  ('MUSIC.CHILDREN', 'QYRIS-INDUSTRY-001', null, 'MUSIC', 'MUSIC · CHILDREN', 0, 2, 'Who inherits and administers this catalogue, and who collects for a contributor who has died or become unreachable?', 'A named list of dependants with an obligation that survives the arrangement ending.', 'Dependants carry the cost of decisions they could not participate in.', 'Check the obligation is written where a dependant or their advocate could actually enforce it.', 'A dependant''s existing claim is never reduced to make a new arrangement work.'),
  ('MUSIC.FAMILY_BOUNDARIES', 'QYRIS-INDUSTRY-001', null, 'MUSIC', 'MUSIC · FAMILY BOUNDARIES', 0, 3, 'Who outside the credited contributors — managers, relatives, label staff, a partner — can hold up a release or take a cut, and who tells them no?', 'A boundary map naming what is decided inside and what is not.', 'Outside interference is rarely about the outsider; it is about who will hold a line with their own people.', 'Test against a real past incident. What happened is the boundary, whatever was intended.', 'Each party holds the line with their own people. Nobody is required to deliver another''s bad news.'),
  ('MUSIC.FAITH_WORLDVIEW', 'QYRIS-INDUSTRY-001', null, 'MUSIC', 'MUSIC · FAITH / WORLDVIEW', 0, 4, 'What is this record actually about, who decides when a song crosses a line, and what happens to an artist who changes their mind about it later?', 'A named governing authority and a stated consequence for dissent.', 'An unnamed governing belief defaults to whoever can invoke one, which is a power question in other clothes.', 'Look at what is scheduled and what is funded. Both record the operative creed more honestly than a statement.', 'Nobody is bound to an authority they did not personally accept, and accepting one does not surrender the right to leave.'),
  ('MUSIC.SEX_INTIMACY', 'QYRIS-INDUSTRY-001', null, 'MUSIC', 'MUSIC · CLOSENESS & POWER', 0, 5, 'Where do closeness and power overlap in this session, tour or writing room, and what happened the last time the person with the least leverage said no?', 'A concrete description of the aftermath of refusal, from both sides.', 'Coercion lives in the aftermath — the silence, the withdrawal, the lost opportunity — rather than in the moment.', 'Compare both accounts of the same past refusal. A gap between them is the finding.', 'If either account describes pressure, retaliation or fear, this stops being a process question and routes to support. No answer is recorded.'),
  ('MUSIC.HOUSEHOLD_LABOR', 'QYRIS-INDUSTRY-001', null, 'MUSIC', 'MUSIC · UNSEEN LABOUR', 0, 6, 'Who does the clearance, the metadata, the registration, the file management and the follow-up that nobody credits and nobody wants?', 'A task inventory with a named owner per line, including remembering and noticing.', 'Unwritten work is allocated by default to whoever notices it first, permanently.', 'Track a real week. Self-report and observation diverge substantially in both directions.', 'Naming an imbalance is information, not an accusation, and is not answered with a list of the other side''s contributions.'),
  ('MUSIC.CONFLICT', 'QYRIS-INDUSTRY-001', null, 'MUSIC', 'MUSIC · CONFLICT', 0, 7, 'When a credit or a split is disputed after release, who decides, on what record, and what is never done — pulling a track, withholding stems, going public first?', 'Described pressure patterns and a short list of unconditional prohibitions.', 'Arrangements do not fail because there is conflict. They fail because of what is permitted during it.', 'Describe the last three real disputes: who escalated, who went silent, how it ended.', 'Threats, retaliation and intimidation are on the prohibited list by default and are not negotiable items.'),
  ('MUSIC.HEALTH_CARE', 'QYRIS-INDUSTRY-001', null, 'MUSIC', 'MUSIC · CAPACITY & CARE', 0, 8, 'What happens to this project if the lead artist cannot work, and who is authorised to approve a release, a licence or a takedown in their place?', 'A named decision-holder for incapacity and a named practical continuity plan.', 'Continuity decisions get made by whoever is present, unless they were made earlier.', 'Confirm the named holder is documented where it would actually be honoured. Intention is not authority.', 'No health detail is stored here. Only the position, the named holder and the document''s existence.'),
  ('MUSIC.CAREERS', 'QYRIS-INDUSTRY-001', null, 'MUSIC', 'MUSIC · PATHS', 0, 9, 'When a tour, a session and a day job collide, whose commitment moves first, and was that rule set before the offer arrived?', 'A decision rule agreed before a specific opportunity is on the table.', 'Without a rule, the party with more leverage wins by default and the other path quietly becomes secondary.', 'Apply the rule to a real opportunity. An untested rule is a sentiment.', 'The rule is symmetrical and reviewable. Deferring once does not establish a permanent order.'),
  ('MUSIC.GEOGRAPHY', 'QYRIS-INDUSTRY-001', null, 'MUSIC', 'MUSIC · PLACE', 0, 10, 'Where is this recorded, mixed, released and toured — and who is farther from home, paying their own travel, or less safe in those venues?', 'A place decision with differential exposure named per person.', 'Two people in the same room can be in materially different countries.', 'Ask the more exposed party. The less exposed party''s assessment is not a measurement.', 'The more exposed party''s assessment governs and is not debated down by someone with a different experience of the same place.'),
  ('MUSIC.PRIVACY', 'QYRIS-INDUSTRY-001', null, 'MUSIC', 'MUSIC · PRIVACY', 0, 11, 'Who holds the session files, the stems, the unreleased material and the personal footage, and can a contributor withdraw their material or their likeness later?', 'A stated privacy line per domain with an explicit revocation right.', 'Access that cannot be revoked is not sharing; it is monitoring.', 'Check whether the uncredited contributor could withdraw access today without a confrontation. If not, that is the real rule.', 'Privacy is not evidence of wrongdoing. A request for it is never recorded as a finding.'),
  ('MUSIC.TRUST', 'QYRIS-INDUSTRY-001', null, 'MUSIC', 'MUSIC · TRUST', 0, 12, 'What would make each person here refuse to work with the others again, and what from the last project is still unsettled?', 'A named breach threshold per party and an inventory of open matters.', 'Arrangements are entered carrying unresolved matter everyone has agreed not to mention.', 'If the list of open matters is empty, ask each party separately. Empty lists are usually courteous.', 'A matter raised here is met once without retaliation, or the question should not have been asked.'),
  ('MUSIC.FUTURE_CHANGE', 'QYRIS-INDUSTRY-001', null, 'MUSIC', 'MUSIC · FUTURE CHANGE', 0, 13, 'If this record succeeds beyond anyone''s expectation, or if a contributor becomes someone the others will not stand beside, what happens to the splits and the credits?', 'A named set of foreseeable changes, a response to each, and a review date in a calendar.', 'Agreements without a review date are enforced against people who have since changed.', 'Test five concrete changes rather than a general willingness to adapt.', 'Any party may call a review early without justifying why.'),
  ('MUSIC.DEAL_BREAKERS', 'QYRIS-INDUSTRY-001', null, 'MUSIC', 'MUSIC · DEAL BREAKERS', 0, 14, 'What use of this music would each person refuse outright — a campaign, a brand, a film, a political ad — and who can veto it after release?', 'Short unsoftened limit lists, plus a stated floor nobody can remove by agreement.', 'A limit that is never stated is discovered only by being crossed.', 'Check each item is genuinely absolute. Anything with a condition belongs in another axis.', 'Coercion, retaliation, harm to dependants, and control of another''s money, documents or care are on the floor and are not removable by agreement.'),
  ('MUSIC.REPAIR', 'QYRIS-INDUSTRY-001', null, 'MUSIC', 'MUSIC · REPAIR', 0, 15, 'When a credit was wrong or a payment did not arrive, what actually fixed it — a corrected registration and a back-payment, or an apology?', 'A repair sequence that can be followed while upset, and a named escalation for repetition.', 'Arrangements survive on repair capacity far more than on initial compatibility.', 'Check the sequence includes a behaviour change, not only an acknowledgement. Count repeats; four is a number, not a mood.', 'Repair is not the harmed party''s job, and non-acceptance of a repair is not punished.'),
  ('COMEDY.MONEY', 'QYRIS-INDUSTRY-001', null, 'COMEDY', 'COMEDY · MONEY', 0, 0, 'What does each person on this bill actually get paid — door, guarantee, taping fee, back-end — and who saw the settlement?', 'A written map of material, credits, taping fees, back-end and stage time with a named holder and a named mover for each line.', 'In comedy, the money fight is almost always a fight about a number one party never saw.', 'Check the stated position against the set list, the tape, the writers'' room credit and the booking. An impression is not a figure.', 'Disclosure is mutual. The opener or the staff writer is not asked to disclose to someone who has disclosed nothing.'),
  ('COMEDY.DEBT', 'QYRIS-INDUSTRY-001', null, 'COMEDY', 'COMEDY · DEBT', 0, 1, 'What development work, road costs and favours are already owed here, and what is a writer or opener expected to eat before anything is paid?', 'An obligation schedule with a legal owner and an end condition per line.', 'Obligations that predate the arrangement do not end when the arrangement begins.', 'Read the instrument. A remembered obligation is an estimate; a signed one is evidence.', 'A disclosed obligation is a shared map, not a file kept on the opener or the staff writer for later use.'),
  ('COMEDY.CHILDREN', 'QYRIS-INDUSTRY-001', null, 'COMEDY', 'COMEDY · CHILDREN', 0, 2, 'Who is coming up under this room, what are they promised, and does any of it survive the person who promised it leaving?', 'A named list of dependants with an obligation that survives the arrangement ending.', 'Dependants carry the cost of decisions they could not participate in.', 'Check the obligation is written where a dependant or their advocate could actually enforce it.', 'A dependant''s existing claim is never reduced to make a new arrangement work.'),
  ('COMEDY.FAMILY_BOUNDARIES', 'QYRIS-INDUSTRY-001', null, 'COMEDY', 'COMEDY · FAMILY BOUNDARIES', 0, 3, 'Who outside the credited writers — a manager, a network note, a headliner''s friend — can rewrite, cut or take credit, and who says no to them?', 'A boundary map naming what is decided inside and what is not.', 'Outside interference is rarely about the outsider; it is about who will hold a line with their own people.', 'Test against a real past incident. What happened is the boundary, whatever was intended.', 'Each party holds the line with their own people. Nobody is required to deliver another''s bad news.'),
  ('COMEDY.FAITH_WORLDVIEW', 'QYRIS-INDUSTRY-001', null, 'COMEDY', 'COMEDY · FAITH / WORLDVIEW', 0, 4, 'What does this room believe is fair game, who rules when a bit crosses a line, and what happens to a comic who stops agreeing?', 'A named governing authority and a stated consequence for dissent.', 'An unnamed governing belief defaults to whoever can invoke one, which is a power question in other clothes.', 'Look at what is scheduled and what is funded. Both record the operative creed more honestly than a statement.', 'Nobody is bound to an authority they did not personally accept, and accepting one does not surrender the right to leave.'),
  ('COMEDY.SEX_INTIMACY', 'QYRIS-INDUSTRY-001', null, 'COMEDY', 'COMEDY · CLOSENESS & POWER', 0, 5, 'Where do closeness and power overlap on this bill or in this room, and what happened after the person with the least leverage last said no to a late invitation?', 'A concrete description of the aftermath of refusal, from both sides.', 'Coercion lives in the aftermath — the silence, the withdrawal, the lost opportunity — rather than in the moment.', 'Compare both accounts of the same past refusal. A gap between them is the finding.', 'If either account describes pressure, retaliation or fear, this stops being a process question and routes to support. No answer is recorded.'),
  ('COMEDY.HOUSEHOLD_LABOR', 'QYRIS-INDUSTRY-001', null, 'COMEDY', 'COMEDY · UNSEEN LABOUR', 0, 6, 'Who books, drives, handles the room, cuts the tape and follows up on payment — and is that person also on the bill?', 'A task inventory with a named owner per line, including remembering and noticing.', 'Unwritten work is allocated by default to whoever notices it first, permanently.', 'Track a real week. Self-report and observation diverge substantially in both directions.', 'Naming an imbalance is information, not an accusation, and is not answered with a list of the other side''s contributions.'),
  ('COMEDY.CONFLICT', 'QYRIS-INDUSTRY-001', null, 'COMEDY', 'COMEDY · CONFLICT', 0, 7, 'When a joke is claimed by two people, who decides, on what record, and what is never done — burning someone publicly, blacklisting, going to the club first?', 'Described pressure patterns and a short list of unconditional prohibitions.', 'Arrangements do not fail because there is conflict. They fail because of what is permitted during it.', 'Describe the last three real disputes: who escalated, who went silent, how it ended.', 'Threats, retaliation and intimidation are on the prohibited list by default and are not negotiable items.'),
  ('COMEDY.HEALTH_CARE', 'QYRIS-INDUSTRY-001', null, 'COMEDY', 'COMEDY · CAPACITY & CARE', 0, 8, 'What happens to this tour or taping when someone cannot go on, and who is authorised to cancel without it ending their standing in the room?', 'A named decision-holder for incapacity and a named practical continuity plan.', 'Continuity decisions get made by whoever is present, unless they were made earlier.', 'Confirm the named holder is documented where it would actually be honoured. Intention is not authority.', 'No health detail is stored here. Only the position, the named holder and the document''s existence.'),
  ('COMEDY.CAREERS', 'QYRIS-INDUSTRY-001', null, 'COMEDY', 'COMEDY · PATHS', 0, 9, 'When a spot, a taping and a paying date collide, whose commitment moves first, and who told the other they had to give it up?', 'A decision rule agreed before a specific opportunity is on the table.', 'Without a rule, the party with more leverage wins by default and the other path quietly becomes secondary.', 'Apply the rule to a real opportunity. An untested rule is a sentiment.', 'The rule is symmetrical and reviewable. Deferring once does not establish a permanent order.'),
  ('COMEDY.GEOGRAPHY', 'QYRIS-INDUSTRY-001', null, 'COMEDY', 'COMEDY · PLACE', 0, 10, 'Which rooms and cities is each comic on this bill actually safe in, who is travelling farthest on their own money, and who gets the hotel?', 'A place decision with differential exposure named per person.', 'Two people in the same room can be in materially different countries.', 'Ask the more exposed party. The less exposed party''s assessment is not a measurement.', 'The more exposed party''s assessment governs and is not debated down by someone with a different experience of the same place.'),
  ('COMEDY.PRIVACY', 'QYRIS-INDUSTRY-001', null, 'COMEDY', 'COMEDY · PRIVACY', 0, 11, 'Who owns the tape of a set that was not meant to be recorded, who can post it, and can a comic have it taken down?', 'A stated privacy line per domain with an explicit revocation right.', 'Access that cannot be revoked is not sharing; it is monitoring.', 'Check whether the opener or the staff writer could withdraw access today without a confrontation. If not, that is the real rule.', 'Privacy is not evidence of wrongdoing. A request for it is never recorded as a finding.'),
  ('COMEDY.TRUST', 'QYRIS-INDUSTRY-001', null, 'COMEDY', 'COMEDY · TRUST', 0, 12, 'What would make each person here never work this room again, and what from the last taping has still not been settled?', 'A named breach threshold per party and an inventory of open matters.', 'Arrangements are entered carrying unresolved matter everyone has agreed not to mention.', 'If the list of open matters is empty, ask each party separately. Empty lists are usually courteous.', 'A matter raised here is met once without retaliation, or the question should not have been asked.'),
  ('COMEDY.FUTURE_CHANGE', 'QYRIS-INDUSTRY-001', null, 'COMEDY', 'COMEDY · FUTURE CHANGE', 0, 13, 'If a bit from this room becomes the special, or if a comic here becomes someone the others will not share a bill with, what happens to the credit and the money?', 'A named set of foreseeable changes, a response to each, and a review date in a calendar.', 'Agreements without a review date are enforced against people who have since changed.', 'Test five concrete changes rather than a general willingness to adapt.', 'Any party may call a review early without justifying why.'),
  ('COMEDY.DEAL_BREAKERS', 'QYRIS-INDUSTRY-001', null, 'COMEDY', 'COMEDY · DEAL BREAKERS', 0, 14, 'What material, booking or brand association would each person here refuse outright, and can they refuse without losing their spot?', 'Short unsoftened limit lists, plus a stated floor nobody can remove by agreement.', 'A limit that is never stated is discovered only by being crossed.', 'Check each item is genuinely absolute. Anything with a condition belongs in another axis.', 'Coercion, retaliation, harm to dependants, and control of another''s money, documents or care are on the floor and are not removable by agreement.'),
  ('COMEDY.REPAIR', 'QYRIS-INDUSTRY-001', null, 'COMEDY', 'COMEDY · REPAIR', 0, 15, 'When credit was taken or a payment was short, what actually fixed it — a corrected credit and the money, or a drink after the show?', 'A repair sequence that can be followed while upset, and a named escalation for repetition.', 'Arrangements survive on repair capacity far more than on initial compatibility.', 'Check the sequence includes a behaviour change, not only an acknowledgement. Count repeats; four is a number, not a mood.', 'Repair is not the harmed party''s job, and non-acceptance of a repair is not punished.'),
  ('BUSINESS.MONEY', 'QYRIS-INDUSTRY-001', null, 'BUSINESS', 'BUSINESS · MONEY', 0, 0, 'What is the actual cap table, what is in the bank, what is committed, and who can move money without a second signature?', 'A written map of equity, revenue, payroll and reserves with a named holder and a named mover for each line.', 'In business, the money fight is almost always a fight about a number one party never saw.', 'Check the stated position against the cap table, the operating agreement and the books. An impression is not a figure.', 'Disclosure is mutual. The early employee without documented equity is not asked to disclose to someone who has disclosed nothing.'),
  ('BUSINESS.DEBT', 'QYRIS-INDUSTRY-001', null, 'BUSINESS', 'BUSINESS · DEBT', 0, 1, 'What is already owed — loans, deferred salary, unpaid invoices, personal guarantees — and which of it follows a founder personally after shutdown?', 'An obligation schedule with a legal owner and an end condition per line.', 'Obligations that predate the arrangement do not end when the arrangement begins.', 'Read the instrument. A remembered obligation is an estimate; a signed one is evidence.', 'A disclosed obligation is a shared map, not a file kept on the early employee without documented equity for later use.'),
  ('BUSINESS.CHILDREN', 'QYRIS-INDUSTRY-001', null, 'BUSINESS', 'BUSINESS · CHILDREN', 0, 2, 'Who are the employees and customers who depend on this continuing, and what do they get if it stops next quarter?', 'A named list of dependants with an obligation that survives the arrangement ending.', 'Dependants carry the cost of decisions they could not participate in.', 'Check the obligation is written where a dependant or their advocate could actually enforce it.', 'A dependant''s existing claim is never reduced to make a new arrangement work.'),
  ('BUSINESS.FAMILY_BOUNDARIES', 'QYRIS-INDUSTRY-001', null, 'BUSINESS', 'BUSINESS · FAMILY BOUNDARIES', 0, 3, 'Who outside the operating team — an investor, a relative, a former founder — can override a decision, and who tells them no?', 'A boundary map naming what is decided inside and what is not.', 'Outside interference is rarely about the outsider; it is about who will hold a line with their own people.', 'Test against a real past incident. What happened is the boundary, whatever was intended.', 'Each party holds the line with their own people. Nobody is required to deliver another''s bad news.'),
  ('BUSINESS.FAITH_WORLDVIEW', 'QYRIS-INDUSTRY-001', null, 'BUSINESS', 'BUSINESS · FAITH / WORLDVIEW', 0, 4, 'What does this company actually believe it is for, who rules when profit and that purpose conflict, and what happens to someone who stops believing it?', 'A named governing authority and a stated consequence for dissent.', 'An unnamed governing belief defaults to whoever can invoke one, which is a power question in other clothes.', 'Look at what is scheduled and what is funded. Both record the operative creed more honestly than a statement.', 'Nobody is bound to an authority they did not personally accept, and accepting one does not surrender the right to leave.'),
  ('BUSINESS.SEX_INTIMACY', 'QYRIS-INDUSTRY-001', null, 'BUSINESS', 'BUSINESS · CLOSENESS & POWER', 0, 5, 'Where do closeness and power overlap here — reporting lines, founders who are partners, a manager and a direct report — and what happens after the person with less power says no?', 'A concrete description of the aftermath of refusal, from both sides.', 'Coercion lives in the aftermath — the silence, the withdrawal, the lost opportunity — rather than in the moment.', 'Compare both accounts of the same past refusal. A gap between them is the finding.', 'If either account describes pressure, retaliation or fear, this stops being a process question and routes to support. No answer is recorded.'),
  ('BUSINESS.HOUSEHOLD_LABOR', 'QYRIS-INDUSTRY-001', null, 'BUSINESS', 'BUSINESS · UNSEEN LABOUR', 0, 6, 'Who does the support tickets, the compliance, the bookkeeping, the onboarding and the remembering — and is that work in anyone''s title or comp?', 'A task inventory with a named owner per line, including remembering and noticing.', 'Unwritten work is allocated by default to whoever notices it first, permanently.', 'Track a real week. Self-report and observation diverge substantially in both directions.', 'Naming an imbalance is information, not an accusation, and is not answered with a list of the other side''s contributions.'),
  ('BUSINESS.CONFLICT', 'QYRIS-INDUSTRY-001', null, 'BUSINESS', 'BUSINESS · CONFLICT', 0, 7, 'When founders deadlock, who breaks the tie, by what document, and what is never done — locking someone out, withholding payroll, going to customers first?', 'Described pressure patterns and a short list of unconditional prohibitions.', 'Arrangements do not fail because there is conflict. They fail because of what is permitted during it.', 'Describe the last three real disputes: who escalated, who went silent, how it ended.', 'Threats, retaliation and intimidation are on the prohibited list by default and are not negotiable items.'),
  ('BUSINESS.HEALTH_CARE', 'QYRIS-INDUSTRY-001', null, 'BUSINESS', 'BUSINESS · CAPACITY & CARE', 0, 8, 'What happens to this company when a key person cannot work for three months, and who is authorised to sign, pay and decide in their place?', 'A named decision-holder for incapacity and a named practical continuity plan.', 'Continuity decisions get made by whoever is present, unless they were made earlier.', 'Confirm the named holder is documented where it would actually be honoured. Intention is not authority.', 'No health detail is stored here. Only the position, the named holder and the document''s existence.'),
  ('BUSINESS.CAREERS', 'QYRIS-INDUSTRY-001', null, 'BUSINESS', 'BUSINESS · PATHS', 0, 9, 'When two founders want the same role, or one wants out, whose path moves first and what does the other receive?', 'A decision rule agreed before a specific opportunity is on the table.', 'Without a rule, the party with more leverage wins by default and the other path quietly becomes secondary.', 'Apply the rule to a real opportunity. An untested rule is a sentiment.', 'The rule is symmetrical and reviewable. Deferring once does not establish a permanent order.'),
  ('BUSINESS.GEOGRAPHY', 'QYRIS-INDUSTRY-001', null, 'BUSINESS', 'BUSINESS · PLACE', 0, 10, 'Where is this incorporated, where do people actually work, and does anyone''s visa, safety or tax position depend on that answer?', 'A place decision with differential exposure named per person.', 'Two people in the same room can be in materially different countries.', 'Ask the more exposed party. The less exposed party''s assessment is not a measurement.', 'The more exposed party''s assessment governs and is not debated down by someone with a different experience of the same place.'),
  ('BUSINESS.PRIVACY', 'QYRIS-INDUSTRY-001', null, 'BUSINESS', 'BUSINESS · PRIVACY', 0, 11, 'What employee, customer and founder data is held, who can read it, and what happens to it at shutdown or acquisition?', 'A stated privacy line per domain with an explicit revocation right.', 'Access that cannot be revoked is not sharing; it is monitoring.', 'Check whether the early employee without documented equity could withdraw access today without a confrontation. If not, that is the real rule.', 'Privacy is not evidence of wrongdoing. A request for it is never recorded as a finding.'),
  ('BUSINESS.TRUST', 'QYRIS-INDUSTRY-001', null, 'BUSINESS', 'BUSINESS · TRUST', 0, 12, 'What would make each founder walk, and what is currently unsaid between them that everyone has agreed not to raise?', 'A named breach threshold per party and an inventory of open matters.', 'Arrangements are entered carrying unresolved matter everyone has agreed not to mention.', 'If the list of open matters is empty, ask each party separately. Empty lists are usually courteous.', 'A matter raised here is met once without retaliation, or the question should not have been asked.'),
  ('BUSINESS.FUTURE_CHANGE', 'QYRIS-INDUSTRY-001', null, 'BUSINESS', 'BUSINESS · FUTURE CHANGE', 0, 13, 'If this is acquired, if a founder leaves, or if the market disappears, what happens to equity, to employees and to the promises already made?', 'A named set of foreseeable changes, a response to each, and a review date in a calendar.', 'Agreements without a review date are enforced against people who have since changed.', 'Test five concrete changes rather than a general willingness to adapt.', 'Any party may call a review early without justifying why.'),
  ('BUSINESS.DEAL_BREAKERS', 'QYRIS-INDUSTRY-001', null, 'BUSINESS', 'BUSINESS · DEAL BREAKERS', 0, 14, 'What customer, investor, contract or practice would each founder refuse outright, and can one of them veto it alone?', 'Short unsoftened limit lists, plus a stated floor nobody can remove by agreement.', 'A limit that is never stated is discovered only by being crossed.', 'Check each item is genuinely absolute. Anything with a condition belongs in another axis.', 'Coercion, retaliation, harm to dependants, and control of another''s money, documents or care are on the floor and are not removable by agreement.'),
  ('BUSINESS.REPAIR', 'QYRIS-INDUSTRY-001', null, 'BUSINESS', 'BUSINESS · REPAIR', 0, 15, 'When payroll was late or equity was promised and never papered, what actually fixed it — an executed document and the money, or a conversation?', 'A repair sequence that can be followed while upset, and a named escalation for repetition.', 'Arrangements survive on repair capacity far more than on initial compatibility.', 'Check the sequence includes a behaviour change, not only an acknowledgement. Count repeats; four is a number, not a mood.', 'Repair is not the harmed party''s job, and non-acceptance of a repair is not punished.'),
  ('RELIGION.MONEY', 'QYRIS-INDUSTRY-001', null, 'RELIGION', 'RELIGION · MONEY', 0, 0, 'What is given, where does it go, who sees the accounts, and can an ordinary member read them without asking permission?', 'A written map of tithes, offerings, property and trust with a named holder and a named mover for each line.', 'In religion, the money fight is almost always a fight about a number one party never saw.', 'Check the stated position against the minutes, the accounts and the membership roll. An impression is not a figure.', 'Disclosure is mutual. The member with no standing to ask is not asked to disclose to someone who has disclosed nothing.'),
  ('RELIGION.DEBT', 'QYRIS-INDUSTRY-001', null, 'RELIGION', 'RELIGION · DEBT', 0, 1, 'What does this body owe — building loans, personal guarantees by members, obligations to a parent organisation — and who carries it if the congregation dissolves?', 'An obligation schedule with a legal owner and an end condition per line.', 'Obligations that predate the arrangement do not end when the arrangement begins.', 'Read the instrument. A remembered obligation is an estimate; a signed one is evidence.', 'A disclosed obligation is a shared map, not a file kept on the member with no standing to ask for later use.'),
  ('RELIGION.CHILDREN', 'QYRIS-INDUSTRY-001', null, 'RELIGION', 'RELIGION · CHILDREN', 0, 2, 'What happens to children here — who is alone with them, who checked, what is taught, and at what age is a child''s own position honoured?', 'A named list of dependants with an obligation that survives the arrangement ending.', 'Dependants carry the cost of decisions they could not participate in.', 'Check the obligation is written where a dependant or their advocate could actually enforce it.', 'A child''s safety is never a matter of internal discretion. Any disclosure of harm routes outside this body to the relevant statutory authority, and this system records no detail about any child.'),
  ('RELIGION.FAMILY_BOUNDARIES', 'QYRIS-INDUSTRY-001', null, 'RELIGION', 'RELIGION · FAMILY BOUNDARIES', 0, 3, 'What may leadership decide inside a member''s household — marriage, discipline, schooling, money, medical care — and who tells them that is not theirs?', 'A boundary map naming what is decided inside and what is not.', 'Outside interference is rarely about the outsider; it is about who will hold a line with their own people.', 'Test against a real past incident. What happened is the boundary, whatever was intended.', 'Each party holds the line with their own people. Nobody is required to deliver another''s bad news.'),
  ('RELIGION.FAITH_WORLDVIEW', 'QYRIS-INDUSTRY-001', null, 'RELIGION', 'RELIGION · FAITH / WORLDVIEW', 0, 4, 'Who rules when doctrine is disputed, how is that ruling changed, and what happens socially and materially to a member who stops believing?', 'A named governing authority and a stated consequence for dissent.', 'An unnamed governing belief defaults to whoever can invoke one, which is a power question in other clothes.', 'Look at what is scheduled and what is funded. Both record the operative creed more honestly than a statement.', 'Nobody is bound to an authority they did not personally accept, and accepting one does not surrender the right to leave.'),
  ('RELIGION.SEX_INTIMACY', 'QYRIS-INDUSTRY-001', null, 'RELIGION', 'RELIGION · CLOSENESS & POWER', 0, 5, 'Where do spiritual authority and personal closeness overlap here, and what happened the last time someone with less standing said no to someone with more?', 'A concrete description of the aftermath of refusal, from both sides.', 'Coercion lives in the aftermath — the silence, the withdrawal, the lost opportunity — rather than in the moment.', 'Compare both accounts of the same past refusal. A gap between them is the finding.', 'If either account describes pressure, retaliation or fear, this stops being a process question and routes to support. No answer is recorded.'),
  ('RELIGION.HOUSEHOLD_LABOR', 'QYRIS-INDUSTRY-001', null, 'RELIGION', 'RELIGION · UNSEEN LABOUR', 0, 6, 'Who does the cleaning, the childcare, the cooking, the visiting and the setup — and is that the same group of women every week, unpaid and uncounted?', 'A task inventory with a named owner per line, including remembering and noticing.', 'Unwritten work is allocated by default to whoever notices it first, permanently.', 'Track a real week. Self-report and observation diverge substantially in both directions.', 'Naming an imbalance is information, not an accusation, and is not answered with a list of the other side''s contributions.'),
  ('RELIGION.CONFLICT', 'QYRIS-INDUSTRY-001', null, 'RELIGION', 'RELIGION · CONFLICT', 0, 7, 'When a member disputes leadership, who hears it, is it heard by anyone independent, and what is never done — shunning, disclosure of a confession, withholding a child''s access?', 'Described pressure patterns and a short list of unconditional prohibitions.', 'Arrangements do not fail because there is conflict. They fail because of what is permitted during it.', 'Describe the last three real disputes: who escalated, who went silent, how it ended.', 'Threats, retaliation and intimidation are on the prohibited list by default and are not negotiable items.'),
  ('RELIGION.HEALTH_CARE', 'QYRIS-INDUSTRY-001', null, 'RELIGION', 'RELIGION · CAPACITY & CARE', 0, 8, 'What does this body teach about medical care, and has anyone been discouraged from treatment, medication or a clinician?', 'A named decision-holder for incapacity and a named practical continuity plan.', 'Continuity decisions get made by whoever is present, unless they were made earlier.', 'Confirm the named holder is documented where it would actually be honoured. Intention is not authority.', 'No health detail is stored here. Only the position, the named holder and the document''s existence.'),
  ('RELIGION.CAREERS', 'QYRIS-INDUSTRY-001', null, 'RELIGION', 'RELIGION · PATHS', 0, 9, 'Who is paid here, who is expected to serve for free, and how does someone move from unpaid service to a paid role — or say no without losing standing?', 'A decision rule agreed before a specific opportunity is on the table.', 'Without a rule, the party with more leverage wins by default and the other path quietly becomes secondary.', 'Apply the rule to a real opportunity. An untested rule is a sentiment.', 'The rule is symmetrical and reviewable. Deferring once does not establish a permanent order.'),
